import { z } from "zod";

export const envSchema = z.object({
  /** Inferred from 6 files (examples/cookies/index.js, examples/error-pages/index.js) */
  NODE_ENV: z.string().optional(),
  /** Inferred from 1 files (test/support/env.js) */
  NO_DEPRECATION: z.string(),
});

export type Env = z.infer<typeof envSchema>;

export const env = envSchema.parse(process.env);
